// ===== Universal KPI calculator (reads column names from Settings) =====
const S = $('Settings').first().json;
const rows = $input.all().map(i => i.json);

if (!rows.length) throw new Error('The sheet returned no rows.');
if (!(S.dateColumn in rows[0])) {
  throw new Error(`Column "${S.dateColumn}" not found. Your sheet columns are: ${Object.keys(rows[0]).join(', ')}`);
}

const todayStr = $now.toFormat('yyyy-MM-dd');
const yesterdayStr = $now.minus({ days: 1 }).toFormat('yyyy-MM-dd');
const pad = n => String(n).padStart(2, '0');
const round2 = n => Math.round(n * 100) / 100;

// Handles 2026-10-10, 10/10/2026, Sheets serial numbers and text dates
function normalizeDate(val) {
  if (val === null || val === undefined || val === '') return null;
  if (typeof val === 'number') {
    return new Date(Math.round((val - 25569) * 86400000)).toISOString().slice(0, 10);
  }
  const s = String(val).trim();
  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (m) return `${m[1]}-${pad(m[2])}-${pad(m[3])}`;
  m = s.match(/^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{4})/);
  if (m) {
    const day = S.dayFirst ? m[1] : m[2];
    const month = S.dayFirst ? m[2] : m[1];
    return `${m[3]}-${pad(month)}-${pad(day)}`;
  }
  const d = new Date(s);
  return isNaN(d) ? null : DateTime.fromJSDate(d).toFormat('yyyy-MM-dd');
}

function toNum(v) {
  if (typeof v === 'number') return v;
  const n = parseFloat(String(v ?? '').replace(/[^0-9.-]/g, ''));
  return isNaN(n) ? 0 : n;
}

function revenueOf(r) {
  const v = S.revenueColumn ? r[S.revenueColumn] : undefined;
  if (v !== undefined && v !== '') return toNum(v);
  return toNum(r[S.quantityColumn]) * toNum(r[S.priceColumn]);
}

function rankBy(dataRows, col) {
  const totals = {};
  if (!col) return [];
  dataRows.forEach(r => {
    const key = r[col];
    if (key) totals[key] = (totals[key] || 0) + revenueOf(r);
  });
  return Object.entries(totals).sort((a, b) => b[1] - a[1]);
}

function calcKPIs(dataRows) {
  const revenue = dataRows.reduce((s, r) => s + revenueOf(r), 0);
  const ids = S.orderIdColumn ? new Set(dataRows.map(r => r[S.orderIdColumn]).filter(Boolean)) : null;
  const orders = ids && ids.size ? ids.size : dataRows.length;
  const newCustomers = S.newCustomersColumn
    ? dataRows.reduce((s, r) => s + toNum(r[S.newCustomersColumn]), 0)
    : null;
  const products = rankBy(dataRows, S.productColumn);
  const regions = rankBy(dataRows, S.regionColumn);

  return {
    revenue: round2(revenue),
    orders,
    avgOrderValue: orders ? round2(revenue / orders) : 0,
    newCustomers,
    newCustomersPerOrder: newCustomers !== null && orders ? round2(newCustomers / orders) : null,
    topProduct: products[0]?.[0] || 'N/A',
    topRegion: regions[0]?.[0] || 'N/A',
    worstRegion: regions[regions.length - 1]?.[0] || 'N/A'
  };
}

const today = calcKPIs(rows.filter(r => normalizeDate(r[S.dateColumn]) === todayStr));
const yesterday = calcKPIs(rows.filter(r => normalizeDate(r[S.dateColumn]) === yesterdayStr));

const pct = (t, y) => (y === 0 ? (t === 0 ? 0 : 100) : round2(((t - y) / y) * 100));

return [{
  json: {
    company: S.companyName,
    currency: S.currency || 'USD',
    date: todayStr,
    today,
    yesterday,
    changes: {
      revenue: pct(today.revenue, yesterday.revenue),
      orders: pct(today.orders, yesterday.orders),
      avgOrderValue: pct(today.avgOrderValue, yesterday.avgOrderValue),
      newCustomers: today.newCustomers === null ? null : pct(today.newCustomers, yesterday.newCustomers)
    }
  }
}];

// ===== Universal KPI email builder =====
const ai = $input.first().json;
const aiText =
  ai?.content?.parts?.[0]?.text ||
  ai?.candidates?.[0]?.content?.parts?.[0]?.text ||
  ai?.text || ai?.message?.content || ai?.output ||
  'No summary was generated today.';

const k = $('Calculate KPIs').first().json;
const t = k.today, y = k.yesterday, c = k.changes;

const money = n => {
  try {
    return new Intl.NumberFormat('en-US', { style: 'currency', currency: k.currency }).format(n || 0);
  } catch (e) {
    return k.currency + ' ' + Number(n || 0).toFixed(2);
  }
};
const pct = n => {
  if (n === null || n === undefined) return '';
  const v = Number(n);
  const color = v > 0 ? '#1a7f37' : v < 0 ? '#c62828' : '#555';
  const arrow = v > 0 ? '▲' : v < 0 ? '▼' : '•';
  return `<span style="color:${color}">${arrow} ${v.toFixed(1)}%</span>`;
};

const aiHtml = aiText
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/\*\*(.+?)\*\*/g, '<b>$1</b>')
  .replace(/^#+\s*(.+)$/gm, '<b>$1</b>')
  .replace(/^\s*[-*]\s+(.+)$/gm, '&bull; $1')
  .replace(/\n/g, '<br>');

const cell = 'padding:8px;border-bottom:1px solid #eee';
const row = (label, today, yest, change = '') => `
  <tr><td style="${cell}">${label}</td>
  <td style="${cell};text-align:right"><b>${today}</b></td>
  <td style="${cell};text-align:right">${yest}</td>
  <td style="${cell};text-align:right">${change}</td></tr>`;

let rows =
  row('Revenue', money(t.revenue), money(y.revenue), pct(c.revenue)) +
  row('Orders', t.orders, y.orders, pct(c.orders)) +
  row('Average order value', money(t.avgOrderValue), money(y.avgOrderValue), pct(c.avgOrderValue));
if (t.newCustomers !== null) {
  rows += row('New customers', t.newCustomers, y.newCustomers, pct(c.newCustomers));
}
rows +=
  row('Top product', t.topProduct, y.topProduct) +
  row('Top region', t.topRegion, y.topRegion) +
  row('Worst region', t.worstRegion, y.worstRegion);

const html = `
<div style="font-family:Arial,sans-serif;max-width:640px;margin:auto;color:#222">
  <h2 style="margin-bottom:4px">${k.company} Daily Sales Briefing</h2>
  <div style="color:#777;margin-bottom:16px">${k.date}</div>
  <table style="width:100%;border-collapse:collapse;font-size:14px;margin-bottom:20px">
    <tr style="background:#f4f4f4">
      <th style="padding:8px;text-align:left">KPI</th>
      <th style="padding:8px;text-align:right">Today</th>
      <th style="padding:8px;text-align:right">Yesterday</th>
      <th style="padding:8px;text-align:right">Change</th>
    </tr>
    ${rows}
  </table>
  <h3 style="margin-bottom:8px">Analyst summary</h3>
  <div style="font-size:14px;line-height:1.6">${aiHtml}</div>
</div>`;

const subject = `${k.company} Daily Sales: ${money(t.revenue)} (${Number(c.revenue).toFixed(1)}% vs yesterday) - ${k.date}`;

return [{ json: { subject, html, summaryText: aiText } }];
